const aiItems = $input.all();

/**
 * WICHTIG:
 * Die HTTP Request Node gibt normalerweise nur die AI-Antwort zurück.
 * Deshalb holen wir uns die Originaldaten aus der vorherigen Classify-Mail-Node.
 *
 * Da der Gmail Trigger typischerweise eine Mail pro Durchlauf verarbeitet,
 * reicht diese indexbasierte Zuordnung für deinen Workflow sauber aus.
 */
const originalItems = $items("Classify Mail");

const ALLOWED_LABELS = new Set([
  "AUTO/Amazon",
  "AUTO/Amazon KDP",
  "AUTO/Bank/Haspa",
  "AUTO/Bank/ING",
  "AUTO/PayPal",
  "AUTO/Kreditkarte/Barclays",
  "AUTO/Kreditkarte/Amazon Visa",
  "AUTO/Kreditkarte/Extra Card",
  "AUTO/Fachzeitschriften/Heise",
  "AUTO/Fachzeitschriften/IT Administrator",
  "AUTO/Server/Hetzner",
  "AUTO/Server/IONOS",
  "AUTO/Server/Netcup",
  "AUTO/Server/Hostinger",
  "AUTO/Server/Zap-Hosting",
  "AUTO/Security/CrowdSec",
  "AUTO/KI/OpenAI",
  "AUTO/KI/OpenRouter",
  "AUTO/KI/ChatGPT",
  "AUTO/Video/HeyGen",
  "AUTO/Video/NotebookLM",
  "AUTO/Social/Instagram",
  "AUTO/Social/YouTube",
  "AUTO/Social/TikTok",
  "AUTO/Lieferanten/DHL",
  "AUTO/Lieferanten/DPD",
  "AUTO/Lieferanten/REWE",
  "AUTO/Google/Auswertungen",
  "AUTO/Education/Fernschule Weber",
  "AUTO/Versicherung",
  "AUTO/Auto/ADAC",
  "AUTO/Auto/Shell",
  "AUTO/Auto/Check24",
  "AUTO/Steam",
  "AUTO/Telefon",
  "AUTO/Internet",
  "AUTO/Job/XING",
  "AUTO/Vermieter",
  "AUTO/Dringend",
  "AUTO/SPAM",
  "AUTO/Review",
  "AUTO/Fehler"
]);

const WORKFLOW_LABELS = new Set([
  "AUTO/Dringend",
  "AUTO/SPAM",
  "AUTO/Review",
  "AUTO/Fehler"
]);

function safeJsonParse(value) {
  try {
    return JSON.parse(value);
  } catch {
    return null;
  }
}

function extractAiContent(aiJson) {
  return (
    aiJson?.choices?.[0]?.message?.content ||
    aiJson?.choices?.[0]?.text ||
    aiJson?.message?.content ||
    aiJson?.content ||
    ""
  );
}

function parseAiJson(content) {
  if (typeof content !== "string") {
    return null;
  }

  let parsed = safeJsonParse(content);
  if (parsed) {
    return parsed;
  }

  // Falls die KI doch Markdown oder Text drumherum liefert
  const match = content.match(/\{[\s\S]*\}/);
  if (match) {
    parsed = safeJsonParse(match[0]);
  }

  return parsed;
}

function normalizeLabels(labels) {
  if (!Array.isArray(labels)) {
    return ["AUTO/Review"];
  }

  const valid = labels
    .map(label => String(label || "").trim())
    .filter(label => ALLOWED_LABELS.has(label));

  if (valid.length === 0) {
    return ["AUTO/Review", "AUTO/Fehler"];
  }

  return [...new Set(valid)];
}

return aiItems.map((aiItem, index) => {
  const original = originalItems[index]?.json || {};

  const content = extractAiContent(aiItem.json);
  const parsed = parseAiJson(content);

  let aiLabels = normalizeLabels(parsed?.labels);

  const previousLabels = Array.isArray(original.label_names)
    ? original.label_names
    : [];

  const previousWorkflowLabels = previousLabels.filter(label => WORKFLOW_LABELS.has(label));

  const aiHasRealCategory = aiLabels.some(label => !WORKFLOW_LABELS.has(label));

  let finalLabels = [
    ...previousWorkflowLabels,
    ...aiLabels
  ];

  /**
   * Wenn die KI eine echte Kategorie findet,
   * entfernen wir AUTO/Review.
   */
  if (aiHasRealCategory) {
    finalLabels = finalLabels.filter(label => label !== "AUTO/Review");
  }

  /**
   * Wenn nur AUTO/Review übrig bleibt, ist das okay.
   * Wenn gar nichts übrig bleibt, Sicherheitsfallback.
   */
  finalLabels = [...new Set(finalLabels)];

  if (finalLabels.length === 0) {
    finalLabels = ["AUTO/Review", "AUTO/Fehler"];
  }

  const realCategoryLabels = finalLabels.filter(label => !WORKFLOW_LABELS.has(label));

  return {
    json: {
      ...original,

      ai_response_raw: aiItem.json,
      ai_classification: {
        raw_content: content,
        parsed,
        labels: aiLabels,
        confidence: typeof parsed?.confidence === "number" ? parsed.confidence : null,
        reason: parsed?.reason || "",
        parse_ok: parsed !== null
      },

      label_names: finalLabels,
      primary_label: realCategoryLabels[0] || finalLabels[0] || "AUTO/Review",
      needs_ai: false,
      classification_confidence: typeof parsed?.confidence === "number"
        ? parsed.confidence
        : original.classification_confidence || 0.3,
      classification_source: "ai_fallback"
    }
  };
});
